1	import { Subject, Observable } from "rxjs";
2	import TransportNodeHidSingleton from "@ledgerhq/hw-transport-node-hid-singleton";
3	import { withDevice } from "@ledgerhq/live-common/hw/deviceAccess";
4	import { DisconnectedDeviceDuringOperation, serializeError } from "@ledgerhq/errors";
5	import {
6	  transportCloseChannel,
7	  transportExchangeChannel,
8	  transportExchangeBulkChannel,
9	  transportOpenChannel,
10	  transportExchangeBulkUnsubscribeChannel,
11	  transportListenChannel,
12	} from "~/config/transportChannels";
13	import { MessagesMap } from "./types";
14	
15	type APDUMessage =
16	  | { type: "exchange"; apduHex: string; requestId: string }
17	  | { type: "exchangeBulk"; apdusHex: string[]; requestId: string }
18	  | { type: "exchangeBulkUnsubscribe"; requestId: string };
19	
20	const transports = new Map<string, Subject<APDUMessage>>();
21	const transportsBulkSubscriptions = new Map<string, { unsubscribe: () => void }>();
22	
23	export const transportOpen = ({ data, requestId }: MessagesMap["transport:open"]) => {
24	  const subjectExist = transports.get(data.descriptor);
25	
26	  const onEnd = () => {
27	    process.send?.({
28	      type: transportOpenChannel,
29	      data,
30	      requestId,
31	    });
32	  };
33	
34	  // If already exists simply return success
35	  if (subjectExist) {
36	    return onEnd();
37	  }
38	
39	  withDevice(data.descriptor)(transport => {
40	    const subject = new Subject<APDUMessage>();
41	    subject.subscribe({
42	      next: e => {
43	        if (e.type === "exchange") {
44	          transport
45	            .exchange(Buffer.from(e.apduHex, "hex"))
46	            .then(
47	              response =>
48	                process.send?.({
49	                  type: transportExchangeChannel,
50	                  data: response.toString("hex"),
51	                  requestId: e.requestId,
52	                }),
53	            )
54	            .catch(
55	              error =>
56	                process.send?.({
57	                  type: transportExchangeChannel,
58	                  error: serializeError(error),
59	                  requestId: e.requestId,
60	                }),
61	            );
62	        } else if (e.type === "exchangeBulk") {
63	          const apdus = e.apdusHex.map(apduHex => Buffer.from(apduHex, "hex"));
64	          const subscription = transport.exchangeBulk(apdus, {
65	            next: response => {
66	              process.send?.({
67	                type: transportExchangeBulkChannel,
68	                data: response.toString("hex"),
69	                requestId: e.requestId,
70	              });
71	            },
72	            error: error => {
73	              process.send?.({
74	                type: transportExchangeBulkChannel,
75	                error: serializeError(error as Parameters<typeof serializeError>[0]),
76	                requestId: e.requestId,
77	              });
78	            },
79	            complete: () => {
80	              process.send?.({
81	                type: transportExchangeBulkChannel,
82	                requestId: e.requestId,
83	              });
84	            },
85	          });
86	          transportsBulkSubscriptions.set(e.requestId, subscription);
87	        } else if (e.type === "exchangeBulkUnsubscribe") {
88	          const subscription = transportsBulkSubscriptions.get(e.requestId);
89	          if (subscription) {
90	            subscription.unsubscribe();
91	            transportsBulkSubscriptions.delete(e.requestId);
92	          }
93	        }
94	      },
95	      complete: () => {
96	        transports.delete(data.descriptor);
97	      },
98	    });
99	
100	    transports.set(data.descriptor, subject);
101	
102	    onEnd();
103	
104	    return subject;
105	  }).subscribe({
106	    error: error => {
107	      process.send?.({
108	        type: transportOpenChannel,
109	        error: serializeError(error),
110	        requestId,
111	      });
112	    },
113	  });
114	};
115	
116	export const transportExchange = ({ data, requestId }: MessagesMap["transport:exchange"]) => {
117	  const subject = transports.get(data.descriptor);
118	  if (!subject) {
119	    process.send?.({
120	      type: transportExchangeChannel,
121	      error: serializeError(
122	        new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
123	      ),
124	      requestId,
125	    });
126	    return;
127	  }
128	  subject.next({ type: "exchange", apduHex: data.apduHex, requestId });
129	};
130	
131	export const transportExchangeBulk = ({
132	  data,
133	  requestId,
134	}: MessagesMap["transport:exchangeBulk"]) => {
135	  const subject = transports.get(data.descriptor);
136	  if (!subject) {
137	    process.send?.({
138	      type: transportExchangeBulkChannel,
139	      error: serializeError(
140	        new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
141	      ),
142	      requestId,
143	    });
144	    return;
145	  }
146	  // apduHex isn't used for bulk case
147	  subject.next({ type: "exchangeBulk", apdusHex: data.apdusHex, requestId });
148	};
149	
150	export const transportExchangeBulkUnsubscribe = ({
151	  data,
152	  requestId,
153	}: MessagesMap["transport:exchangeBulk:unsubscribe"]) => {
154	  const subject = transports.get(data.descriptor);
155	  if (!subject) {
156	    process.send?.({
157	      type: transportExchangeBulkUnsubscribeChannel,
158	      error: serializeError(
159	        new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
160	      ),
161	      requestId,
162	    });
163	    return;
164	  }
165	  subject.next({ type: "exchangeBulkUnsubscribe", requestId });
166	};
167	
168	const transportListenListeners = new Map<string, { unsubscribe: () => void }>();
169	
170	export const transportListen = ({ requestId }: MessagesMap["transport:listen"]) => {
171	  const observable = new Observable(TransportNodeHidSingleton.listen);
172	  const subscription = observable.subscribe({
173	    next: e => {
174	      process.send?.({
175	        type: transportListenChannel,
176	        data: e,
177	        requestId,
178	      });
179	    },
180	    error: error => {
181	      process.send?.({
182	        type: transportListenChannel,
183	        error: serializeError(error),
184	        requestId,
185	      });
186	    },
187	  });
188	  transportListenListeners.set(requestId, subscription);
189	};
190	
191	export const transportListenUnsubscribe = ({
192	  requestId,
193	}: MessagesMap["transport:listen:unsubscribe"]) => {
194	  const listener = transportListenListeners.get(requestId);
195	  if (listener) {
196	    listener.unsubscribe();
197	    transportListenListeners.delete(requestId);
198	  }
199	};
200	
201	export const transportClose = ({ data, requestId }: MessagesMap["transport:close"]) => {
202	  const subject = transports.get(data.descriptor);
203	  if (!subject) {
204	    process.send?.({
205	      type: transportCloseChannel,
206	      error: serializeError(
207	        new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
208	      ),
209	      requestId,
210	    });
211	    return;
212	  }
213	  subject.subscribe({
214	    complete: () => {
215	      process.send?.({
216	        type: transportCloseChannel,
217	        data,
218	        requestId,
219	      });
220	    },
221	  });
222	  subject.complete();
223	};
