import { DisconnectedDeviceDuringOperation, serializeError } from "@ledgerhq/errors";
import { MessagesMap } from "./types";

// A structured response emitted by each transport handler observable.
// Success responses carry a `data` field, failures carry a serialized `error`.
export type TransportResponse =
  | { data: unknown }
  | { error: unknown }
  | { type: "ok"; data: unknown };

// Keeps track of the opened transports, keyed by their device descriptor.
const transports = new Map<string, Transport>();

// Keeps track of the `transportListen` subscribers, keyed by their requestId,
// so that a matching `transportListenUnsubscribe` can complete them.
const transportListenListeners = new Map<string, Subscriber<TransportResponse>>();

/**
 * Opens a transport for the given device descriptor.
 *
 * If a transport is already opened for this descriptor, or if a registered
 * transport module is able to open it, a response with a `data` field is emitted.
 * If no transport module supports the descriptor, an error response (whose name
 * is `CantOpenDevice`) is emitted.
 */
export const transportOpen = ({ data }: MessagesMap["transport:open"]): Observable<TransportResponse> => {
  return new Observable<TransportResponse>(subscriber => {
    const existingTransport = transports.get(data.descriptor);

    // If a transport is already opened for this descriptor, simply return success.
    if (existingTransport) {
      subscriber.next({ data });
      subscriber.complete();
      return;
    }

    open(data.descriptor)
      .then(transport => {
        transports.set(data.descriptor, transport);
        subscriber.next({ data });
        subscriber.complete();
      })
      .catch(error => {
        subscriber.next({ error: serializeError(error) });
        subscriber.complete();
      });
  });
};

/**
 * Exchanges a single APDU with the transport opened for the given descriptor.
 *
 * Emits a response with a `data` field containing the hex string of the response
 * buffer on success. If no transport is opened, or if the exchange fails, an error
 * response (whose name is `DisconnectedDeviceDuringOperation`) is emitted.
 */
export const transportExchange = ({
  data,
}: MessagesMap["transport:exchange"]): Observable<TransportResponse> => {
  return new Observable<TransportResponse>(subscriber => {
    const transport = transports.get(data.descriptor);

    if (!transport) {
      subscriber.next({
        error: serializeError(
          new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
        ),
      });
      subscriber.complete();
      return;
    }

    transport
      .exchange(Buffer.from(data.apduHex, "hex"))
      .then(response => {
        subscriber.next({ data: response.toString("hex") });
        subscriber.complete();
      })
      .catch(error => {
        subscriber.next({ error: serializeError(error) });
        subscriber.complete();
      });
  });
};

/**
 * Exchanges a bulk of APDUs with the transport opened for the given descriptor.
 *
 * Emits one response per APDU: a `data` field on success, or an `error` field on
 * failure. If no transport is opened, a single error response (whose name is
 * `DisconnectedDeviceDuringOperation`) is emitted.
 */
export const transportExchangeBulk = ({
  data,
}: MessagesMap["transport:exchangeBulk"]): Observable<TransportResponse> => {
  return new Observable<TransportResponse>(subscriber => {
    const transport = transports.get(data.descriptor);

    if (!transport) {
      subscriber.next({
        error: serializeError(
          new DisconnectedDeviceDuringOperation("No open transport for the given descriptor"),
        ),
      });
      subscriber.complete();
      return;
    }

    const apdus = data.apdusHex.map(apduHex => Buffer.from(apduHex, "hex"));
    const subscription = transport.exchangeBulk(apdus, {
      next: response => {
        subscriber.next({ data: response.toString("hex") });
      },
      error: error => {
        subscriber.next({
          error: serializeError(error as Parameters<typeof serializeError>[0]),
        });
      },
      complete: () => {
        subscriber.complete();
      },
    });

    return () => {
      subscription?.unsubscribe?.();
    };
