,EAAE,uBAAuB;yBACnC,CAAC;wBAEF,2BAA2B;wBAC3B,IAAA,oCAAiB,EAAC,cAAc,CAAC,CAAC,SAAS,CAAC;4BAC1C,IAAI,EAAE,QAAQ,CAAC,EAAE;gCACf,IAAI;oCACF,IAAA,gBAAM,EAAC,QAAQ,CAAC,CAAC,OAAO,CACtB,gBAAM,CAAC,gBAAgB,CAAC;wCACtB,KAAK,EAAE,gBAAM,CAAC,gBAAgB,CAAC,EAAE,IAAI,EAAE,mCAAmC,EAAE,CAAC;qCAC9E,CAAC,CACH,CAAC;oCAEF,kEAAkE;oCAClE,IAAI,kBAAkB,EAAE;wCACtB,IAAI,EAAE,CAAC;qCACR;yCAAM;wCACL,IAAI,CAAC,gEAAgE,CAAC,CAAC;qCACxE;iCACF;gCAAC,OAAO,WAAW,EAAE;oCACpB,IAAI,CAAC,WAAoB,CAAC,CAAC;iCAC5B;4BACH,CAAC;4BACD,KAAK,EAAE,KAAK,CAAC,EAAE;gCACb,OAAO,CAAC,GAAG,CAAC,aAAa,KAAK,EAAE,EAAE,EAAE,KAAK,EAAE,CAAC,CAAC;gCAC7C,IAAI,CAAC,KAAK,CAAC,CAAC;4BACd,CAAC;yBACF,CAAC,CAAC;oBACL,CAAC;iBACF,CAAC,CAAC;YACL,CAAC,CAAC,CAAC;QACL,CAAC,CAAC,CAAC;IACL,CAAC,CAAC,CAAC;AACL,CAAC,CAAC,CAAC","names":[],"sources":["/workspace/repo/apps/ledger-live-desktop/src/internal/__tmp_transportHandler.test.ts"],"sourcesContent":["/* eslint-disable @typescript-eslint/no-explicit-any */\nimport { beforeAll, describe, expect, jest, test } from \"@jest/globals\";\nimport {\n  transportClose,\n  transportExchange,\n  transportExchangeBulk,\n  transportListen,\n  transportListenUnsubscribe,\n  transportOpen,\n} from \"./transportHandler\";\nimport { MessagesMap } from \"./types\";\nimport { registerTransportModule } from \"@ledgerhq/live-common/hw/index\";\nimport { aTransportBuilder } from \"@ledgerhq/hw-transport-mocker\";\nimport { beforeEach } from \"node:test\";\nimport Transport from \"@ledgerhq/hw-transport\";\nimport { Observer, Subject, firstValueFrom } from \"rxjs\";\nimport { DisconnectedDeviceDuringOperation } from \"@ledgerhq/errors\";\nimport TransportNodeHidSingleton, {\n  ListenDescriptorEvent,\n} from \"@ledgerhq/hw-transport-node-hid-singleton\";\n\ndescribe(\"transportHandler\", () => {\n  describe(\"transportOpen\", () => {\n    test(\"When no transport module associated to the tested device has been registered, it should return an error\", done => {\n      const params: MessagesMap[\"transport:open\"] = {\n     