oB,UAAU,CAAC,EAAE;QACpD,MAAM,SAAS,GAAG,UAAU,CAAC,GAAG,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;QAElD,IAAI,CAAC,SAAS,EAAE;YACd,UAAU,CAAC,IAAI,CAAC;gBACd,KAAK,EAAE,IAAA,uBAAc,EACnB,IAAI,0CAAiC,CAAC,4CAA4C,CAAC,CACpF;aACF,CAAC,CAAC;YACH,UAAU,CAAC,QAAQ,EAAE,CAAC;YACtB,OAAO;SACR;QAED,OAAO,CAAC,OAAO,CAAC,SAAS,CAAC,KAAK,EAAE,CAAC;aAC/B,IAAI,CAAC,GAAG,EAAE;YACT,UAAU,CAAC,MAAM,CAAC,IAAI,CAAC,UAAU,CAAC,CAAC;YACnC,UAAU,CAAC,IAAI,CAAC,EAAE,IAAI,EAAE,IAAI,EAAE,IAAI,EAAE,CAAC,CAAC;YACtC,UAAU,CAAC,QAAQ,EAAE,CAAC;QACxB,CAAC,CAAC;aACD,KAAK,CAAC,KAAK,CAAC,EAAE;YACb,UAAU,CAAC,IAAI,CAAC,EAAE,KAAK,EAAE,IAAA,uBAAc,EAAC,KAAK,CAAC,EAAE,CAAC,CAAC;YAClD,UAAU,CAAC,QAAQ,EAAE,CAAC;QACxB,CAAC,CAAC,CAAC;IACP,CAAC,CAAC,CAAC;AACL,CAAC,CAAC;AA3BW,QAAA,cAAc,kBA2BzB","names":[],"sources":["/workspace/repo/apps/ledger-live-desktop/src/internal/transportHandler.ts"],"sourcesContent":["import { Observable, Subscriber } from \"rxjs\";\nimport TransportNodeHidSingleton from \"@ledgerhq/hw-transport-node-hid-singleton\";\nimport Transport from \"@ledgerhq/hw-transport\";\nimport { open } from \"@ledgerhq/live-common/hw/index\";\nimport { DisconnectedDeviceDuringOperation, serializeError } from \"@ledgerhq/errors\";\nimport { MessagesMap } from \"./types\";\n\n// A structured response emitted by each transport handler observable.\n// Success responses carry a `data` field, failures carry a serialized `error`.\nexport type TransportResponse =\n  | { data: unknown }\n  | { error: unknown }\n  | { type: \"ok\"; data: unknown };\n\n// Keeps track of the opened transports, keyed by their device descriptor.\nconst transports = new Map<string, Transport>();\n\n// Keeps track of the `transportListen` subscribers, keyed by their requestId,\n// so that a matching `transportListenUnsubscribe` can complete them.\nconst transportListenListeners = new Map<string, Subscriber<TransportResponse>>();\n\n/**\n * Opens a transport for the given device descriptor.\n *\n * If a transport is already opened for this descriptor, or if a registered\n * transport module is able to open it, a response with a `data` field is emitted.\n * If no transport module supports the descriptor, an error response (whose name\n * is `CantOpenDevice`) is emitted.\n */\nexport const transportOpen = ({ data }: MessagesMap[\"transport:open\"]): Observable<TransportResponse> => {\n  return new Observable<TransportResponse>(subscriber => {\n    const existingTransport = transports.get(data.descriptor);\n\n    // If a transport is already opened for this descriptor, simply return success.\n    if (existingTransport) {\n      subscriber.next({ data });\n      subscriber.complete();\n      return;\n    }\n\n    open(data.descriptor)\n      .then(transport => {\n        transports.set(data.descriptor, transport);\n        subscriber.next({ data });\n        subscriber.complete();\n      })\n      .catch(error => {\n        subscriber.next({ error: serializeError(error) });\n        subscriber.complete();\n      });\n  });\n};\n\n/**\n * Exchanges a single APDU with the transport opened for the given descriptor.\n *\n * Emits a response with a `data` field containing the hex string of the response\n * buffer on success. If no transport is opened, or if the exchange fails, an error\n * response (whose name is `DisconnectedDeviceDuringOperation`) is emitted.\n */\nexport const transportExchange = ({\n  data,\n}: MessagesMap[\"transport:exchange\"]): Observable<TransportResponse> => {\n  return new Observable<TransportResponse>(subscriber => {\n    const transport = transports.get(data.descriptor);\n\n    if (!transport) {\n      subscriber.next({\n        error: serializeError(\n          new DisconnectedDeviceDuringOperation(\"No open transport for the given descriptor\"),\n        ),\n      });\n      subscriber.complete();\n      return;\n    }\n\n    transport\n      .exchange(Buffer.from(data.apduHex, \"hex\"))\n      .then(response => {\n        subscriber.next({ data: response.toString(\"hex\") });\n        subscriber.complete();\n      })\n      .catch(error => {\n        subscriber.next({ error: serializeError(error) });\n        subscriber.complete();\n      });\n  });\n};\n\n/**\n * Exchanges a bulk of APDUs with the transport opened for the given descriptor.\n *\n * Emits one response per APDU: a `data` field on success, or an `error` field on\n * failure. If no transport is opened, a single error response (whose name is\n * `DisconnectedDeviceDuringOperation`) is emitted.\n */\nexport const transportExchangeBulk = ({\n  data,\n}: MessagesMap[\"transport:exchangeBulk\"]): Observable<TransportResponse> => {\n  return new Observable<TransportResponse>(subscriber => {\n    const transport = transports.get(data.descriptor);\n\n    if (!transport) {\n      subscriber.next({\n        error: serializeError(\n          new DisconnectedDeviceDuringOperation(\"No open transport for the given descriptor\"),\n        ),\n      });\n      subscriber.complete();\n      return;\n    }\n\n    const apdus = data.apdusHex.map(apduHex => Buffer.from(apduHex, \"hex\"));\n    const subscription = transport.exchangeBulk(apdus, {\n      next: response => {\n        subscriber.next({ data: response.toString(\"hex\") });\n      },\n      error: error => {\n        subscriber.next({\n          error: serializeError(error as Parameters<typeof serializeError>[0]),\n        });\n      },\n      complete: () => {\n        subscriber.complete();\n      },\n    });\n\n    return () => {\n      subscription?.unsubscribe?.();\n    };\n  });\n};\n\n/**\n * Listens to device connection/disconnection events.\n *\n * Emits an object of shape `{ data: { type: \"add\" | \"remove\", descriptor } }` for\n * each device event, until the observable is unsubscribed (see\n * `transportListenUnsubscribe`).\n */\nexport const transportListen = ({\n  requestId,\n}: MessagesMap[\"transport:listen\"]): Observable<TransportResponse> => {\n  return new Observable<TransportResponse>(subscriber => {\n    const listenSubscription = TransportNodeHidSingleton.listen({\n      next: event => {\n        subscriber.next({ data: event });\n      },\n      error: error => {\n        subscriber.next({ error: serializeError(error) });\n      },\n      complete: () => {\n        subscriber.complete();\n      },\n    });\n\n    transportListenListeners.set(requestId, subscriber);\n\n    return () => {\n      listenSubscription.unsubscribe();\n      transportListenListeners.delete(requestId);\n    };\n  });\n};\n\n/**\n * Stops the `transportListen` observable matching the given requestId, completing\n * it so it stops emitting events.\n *\n * Returns an observable that completes immediately without emitting anything.\n */\nexport const transportListenUnsubscribe = ({\n  requestId,\n}: MessagesMap[\"transport:listen:unsubscribe\"]): Observable<TransportResponse> => {\n  return new Observable<TransportResponse>(subscriber => {\n    const listenSubscriber = transportListenListeners.get(requestId);\n    if (listenSubscriber) {\n      // Completing the `transportListen` subscriber triggers its teardown,\n      // which unsubscribes from the underlying device listener.\n      listenSubscriber.complete();\n    }\n    subscriber.complete();\n  });\n};\n\n/**\n * Closes the transport opened for the given descriptor.\n *\n * Emits `{ type: \"ok\", data }` on success (after having called the underlying\n * transport's `close` method and removed it from the internal store). If no\n * transport is opened, an error response (whose name is\n * `DisconnectedDeviceDuringOperation`) is emitted.\n */\nexport const transportClose = ({\n  data,\n}: MessagesMap[\"transport:close\"]): Observable<TransportResponse> => {\n  return new Observable<TransportResponse>(subscriber => {\n    const transport = transports.get(data.descriptor);\n\n    if (!transport) {\n      subscriber.next({\n        error: serializeError(\n          new DisconnectedDeviceDuringOperation(\"No open transport for the given descriptor\"),\n        ),\n      });\n      subscriber.complete();\n      return;\n    }\n\n    Promise.resolve(transport.close())\n      .then(() => {\n        transports.delete(data.descriptor);\n        subscriber.next({ type: \"ok\", data });\n        subscriber.complete();\n      })\n      .catch(error => {\n        subscriber.next({ error: serializeError(error) });\n        subscriber.complete();\n      });\n  });\n};\n"],"version":3}
